mutations.find:
return `${head}
broker ${t.server}
resolved root ${t.root}
This is a static-auth mesh. Attach still needs this space's seed under ${t.root}/.cotal/auth. Restore the seed at that checkout. This mesh is not open, so attach will not connect without the seed.${shadowLine}`;

mutations.replace:
return `${head}
broker ${t.server}
resolved root ${t.root}
A static-auth mesh keeps this space's seed under <root>/.cotal/auth. That root is what this command resolved and connected with, so if it is not the checkout holding this space's auth, re-register the mesh with \`cotal meshes add ${t.space} --server ${t.server} --root <dir>\`.${shadowLine}`;

mutations.find:
return link.mode === "bare"
  ? standaloneConnectOpts({ tls: link.tls })
  : standaloneConnectOpts({ creds: link.creds, tls: link.tls });

if (target.mode === "auth" && !target.auth) {
  throw new ConnectRefusal(
    `✗ mesh "${target.space}" is a static-auth mesh but the seed under ${target.root} is missing. Restore the seed at that checkout. This mesh is not open.`,
  );
}

mutations.replace:
if (false && target.mode === "auth" && !target.auth) {
  throw new ConnectRefusal(
    `✗ mesh "${target.space}" is a static-auth mesh but the seed under ${target.root} is missing. Restore the seed at that checkout. This mesh is not open.`,
  );
}
